-- Entity of read_data_signals
entity w56cdebf3_handshake_mem_controller_0_read_arbiter_data is
  port (
    rst       : in  std_logic;
    clk       : in  std_logic;
    sel       : in  std_logic_vector(25 - 1 downto 0);
    read_data : in  std_logic_vector(64 - 1 downto 0);
    out_data  : out data_array(25 - 1 downto 0)(64 - 1 downto 0);
    valid     : out std_logic_vector(25 - 1 downto 0);
    nReady    : in  std_logic_vector(25 - 1 downto 0)
  );
